    { "buff.nature.thorns", "snarky", "Danke{ dir|}! {Wer mich jetzt haut, ist selbst schuld.|Jetzt tut's auch mal den anderen weh.}" },
    { "buff.nature.thorns", "snarky", "Oh, danke. {Ab jetzt umarme ich besser niemanden.|Dann umarme ich heute besser keinen.}" },
    { "buff.nature.thorns", "snarky", "Danke{, %t|}. {Endlich lohnt sich das Verprügeltwerden auch mal.|Dann hat das Verprügeltwerden wenigstens einen Sinn.}" },
