    { "buff.nature.thorns", "philosophic", "Danke{, %t|}. {Mal sehen|Ich bin gespannt}, wer das als Erster merkt." },
    { "buff.nature.thorns", "philosophic", "Danke. Jetzt tut jeder Schlag gegen mich auch dem anderen weh." },
