    { "buff.nature.thorns", "cheerful", "Hey, danke! Auf den nächsten Angriff freu ich mich ja richtig." },
    { "buff.nature.thorns", "cheerful", "{Danke|Oh, danke}! Dann sollen sie {ruhig|ruhig mal} zuschlagen!", when = { fight = true } },
