    { "buff.blessing", "polite", "{Danke|Vielen Dank}{, %t|}! {Das ist sehr nett von dir.|Den Segen nehm ich gern.}" },
    { "buff.blessing", "polite", "Oh, danke{ dir|}! Das hilft mir {sehr|wirklich}." },
