    { "emote.friendly.love", "roleplay", "{Vorsicht|Pass auf}{, %t|}, {die Rüstung piekst|meine Rüstung hat scharfe Kanten}." },
    { "emote.friendly.love", "roleplay", "{Oh|Na}, {jemand aus dem anderen Lager|jemand von der anderen Seite}? {Das bleibt unter uns.|Wenn das deine Leute sehen...}", when = { foe = true } },
    { "emote.friendly.love", "snarky", "{Oh, |}{das kam unerwartet|das ging aber schnell}. {Wir kennen uns doch kaum.|Ich kenn ja nicht mal deinen Namen.}" },
    { "emote.friendly.love", "snarky", "{Na|Na so was}, so viel Nähe bin ich gar nicht gewohnt." },
    { "emote.friendly.love", "snarky", "{Langsam|Nicht so schnell}{, %t|}, wir sind doch erst beim Winken." },
    { "emote.friendly.love", "snarky", "Oh, das ist lieb. {Mein Reittier wird aber eifersüchtig.|Ich muss das erst mit meinem Reittier besprechen.}" },
    { "emote.friendly.love", "philosophic", "{Oh.|Na so was.} Das kam {jetzt|} unerwartet." },
    { "emote.friendly.love", "philosophic", "{Oh, |}wir kennen uns doch {kaum|gar nicht}." },
    { "emote.friendly.love", "philosophic", "Das ist {lieb|nett}{, %t|}. Ich wusste nicht, dass man hier so schnell Freunde findet." },
    { "emote.friendly.love", "philosophic", "Na so was{, %t|}. Das passiert mir nicht jeden Tag." },
    { "emote.friendly.love", "cheerful", "{Oh, |}na so was! {Das kam jetzt überraschend.|Damit hab ich nicht gerechnet!}" },
    { "emote.friendly.love", "cheerful", "Haha, wie lieb! {Das ist ja nett von dir.|Da freu ich mich aber.}" },
    { "emote.friendly.love", "cheerful", "Oh, so herzlich? {Na, dann gern!|Das freut mich!}" },
    { "emote.friendly.love", "cheerful", "Na, {so stürmisch|so schnell}? {Da bin ich ja geschmeichelt.|Das bringt mich zum Lachen.}" },
    { "emote.friendly.love", "weary", "{Oh|Na}... das ist {lieb|nett}. Pass auf, sonst schlaf ich dir gleich ein." },
    { "emote.friendly.love", "weary", "Hey{, %t|}... {ich bin viel zu müde für so was.|dafür bin ich heute echt zu müde.}" },
    { "emote.friendly.love", "weary", "{Danke|Oh}, das tut gut nach so einem Tag." },
    { "emote.friendly.love", "weary", "Na, so viel Zuneigung auf einmal? {Ich bin leider völlig erledigt.|Da werd ich ja fast wieder wach.}" },
    { "emote.friendly.thank", "polite", "Gern geschehen{, %t|}!" },
