    { "emote.friendly.thank", "roleplay", "Gern geschehen{, %t|}. Unter Landsleuten {ist das doch klar|hilft man sich}.", when = { kin = true } },
    { "emote.friendly.thank", "snarky", "{Gern geschehen|Keine Ursache}. {Ich weiß zwar nicht mehr, was ich gemacht hab.|Was auch immer ich getan hab.}" },
    { "emote.friendly.thank", "snarky", "{Gerne|Gern geschehen}{, %t|}. {Kommt nicht oft vor, dass ich nützlich bin.|Ich bin selbst überrascht, dass ich helfen konnte.}" },
    { "emote.friendly.thank", "snarky", "Kein Ding. {Die Rechnung schick ich dir per Post.|Ich schreib's dir auf die Rechnung.}" },
    { "emote.friendly.thank", "snarky", "{Bitte|Bitte schön}. Sag's ruhig weiter, {ich brauch den Ruf|ich kann den Ruf gebrauchen}." },
    { "emote.friendly.thank", "philosophic", "Gern geschehen{, %t|}." },
    { "emote.friendly.thank", "philosophic", "Gern{ geschehen|}. {Hätte jeder gemacht.|Das war doch selbstverständlich.}" },
    { "emote.friendly.thank", "philosophic", "{Gern|Kein Problem}. Irgendwann hilft mir auch {jemand|mal einer}." },
    { "emote.friendly.thank", "philosophic", "Gern geschehen. Schön, dass es was gebracht hat." },
