    { "emote.rude", "snarky", "{Schon gut|Ja, ja}, {ich hab heute auch schon besser ausgesehen|ich weiß, ich seh heute nicht so toll aus}." },
    { "emote.rude", "snarky", "{Interessante|Komische} Art, Hallo zu sagen{, %t|}." },
