    { "emote.rude", "weary", "{Ach|Na}... {dafür bin ich heute echt zu müde.|heute nicht, bitte.}" },
    { "emote.rude", "weary", "{Schon gut|Ja, ja}. {Ich hab heute schon Schlimmeres erlebt.|Das war heute noch das Harmloseste.}" },
    { "emote.rude", "weary", "Hm. {Ich tu einfach so, als hätt ich das nicht gesehen.|Ich bin zu müde, um mich drüber aufzuregen.}" },
